import {initCosmic} from './cosmic-progression.js?v=18';
// Local development privileges only: never an authentication/authorization role.
import {convertCatalogItem} from './equipment.js?v=18';
import {COMPANIONS} from './companions.js?v=18';
import {CASH_PRODUCTS} from './ascension.js?v=18';
import {runeValue} from './runes.js?v=18';
export const GM_BUILD=true,GM_RESERVE=999999999;
export function refillGM(p){if(p.localRole!=='gm')return;p.gold=GM_RESERVE;p.wallet||={};p.wallet.cash=GM_RESERVE;p.shards=1000000;p.runes=1000000;p.pots={hp:9999,mp:9999};for(const key of Object.keys(p.materials||{}))p.materials[key]=1000000;}
export function provisionGM(p,content,force=false){if(!content?.items)return false;if(p.gmBuild===18&&!force){refillGM(p);return false;}p.localRole='gm';p.gmBuild=18;p.testMode=true;p.level=1000;p.xp=0;p.wallet||={};p.materials||={};p.companions||={};p.companions.owned=Object.fromEntries(COMPANIONS.map(d=>[d.id,{rank:500}]));p.companions.pet=p.classId==='VIG'?'fox':'drake';p.companions.mount='panther';p.companions.mounted=false;p.magicula={rank:500};p.wings={rank:500,style:'mystic',visible:true};p.aura={rank:500,style:'mystic',visible:true};p.skillRanks=Object.fromEntries(Array.from({length:7},(_,i)=>[i,20]));p.appearances=[...new Set([...(p.appearances||[]),...CASH_PRODUCTS.filter(x=>x.kind==='appearance').map(x=>x.id)])];p.attributes=p.classId==='ARC'?{for:50,int:1125,des:70}:p.classId==='VIG'||p.classId==='ESP'?{for:200,int:0,des:1045}:p.classId==='LAS'?{for:415,int:415,des:415}:{for:975,int:0,des:270};
for(const k of ['for','int','des'])p.attributes[k]*=4;p.attributes.des+=15;if(p.classId==='ARC')p.passive='barrier';initCosmic(p);p.relic={rank:590,id:p.classId==='VIG'?'comet':p.classId==='BAS'?'aegis':'rift'};p.constellation={rank:500,sign:p.classId==='VIG'?8:p.classId==='ARC'?10:p.classId==='BAS'?1:0};p.soul={vital:100,sight:100,edge:100,resolve:100,spark:100};
for(const src of content.items){for(const key of Object.keys(src.recipe_components||{}))if(key!=='gold')p.materials[key]=1000000;}for(const key of ['Pluma Astral','Essência de Aura','Núcleo de Cataclismo','Fragmento de Magícula','Cristal de Vínculo','Essência de Montaria','Extensor Astral','Fragmento de Extensor','Fragmento da Origem','Selo_da_Origem','Fragmento de Relíquia','Poeira de Constelação','Cristal da Alma'])p.materials[key]=1000000;
for(const src of content.items.filter(i=>i.class_id===p.classId&&i.tier==='ORI')){let item=p.bag.find(i=>i.sourceId===src.id);const full=convertCatalogItem(src,true);if(item)Object.assign(item,{...full,id:item.id});else{item=full;p.bag.push(item);}item.enchant=100;const priority=p.classId==='VIG'?['crit','critd','haste','pen','af','precisao']:p.classId==='ARC'?['crit','critd','ampM','am','penM','cdr']:p.classId==='BAS'?['critres','ampres','critd','ten','dr','pvp']:p.classId==='LAS'?['crit','critd','ampF','ampM','pen','cdr']:['crit','critd','ampF','pen','af','cdr'];const pct=['crit','critd','haste','ampF','ampM','cdr','critres','ten','pvp','maxcrit','critdres','ampres'];item.options=Object.entries(src.native_caps).sort((a,b)=>(priority.indexOf(a[0])<0?99:priority.indexOf(a[0]))-(priority.indexOf(b[0])<0?99:priority.indexOf(b[0]))).slice(0,3).map(([type,cap])=>({type,cap:cap/(pct.includes(type)?100:1),value:cap/(pct.includes(type)?100:1)}));item.slots=3;const types=p.classId==='ARC'?['ampM','critd','critd']:p.classId==='VIG'?['critd','critd','critd']:p.classId==='LAS'?['ampF','ampM','critd']:['ampF','critd','critd'];item.runes=[];for(const type of types){const r={type,rule:'cabal05',value:0};item.runes.push(r);r.value=runeValue(item,r,item.runes.length-1);}p.equipped[item.slot]=item.id;}
if(p.classId==='RUP')p.equipped.secondary=null;p.hp=0;p.mp=null;refillGM(p);return true;}
export function updateGMRoster(rows,p){if(p.localRole!=='gm'||!p.heroId)return rows;return [...rows.filter(x=>x.heroId!==p.heroId),structuredClone(p)].slice(-14);}
